import{_ as e,o,c as r,a4 as t}from"./chunks/framework.BBs01uty.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/node-memory.md","filePath":"books/node-memory.md"}'),l={name:"books/node-memory.md"};function i(d,a,n,s,h,c){return o(),r("div",null,[...a[0]||(a[0]=[t('<h2 id="node内存管理" tabindex="-1">Node内存管理 <a class="header-anchor" href="#node内存管理" aria-label="Permalink to &quot;Node内存管理&quot;">​</a></h2><h4 id="堆内存大小" tabindex="-1">堆内存大小 <a class="header-anchor" href="#堆内存大小" aria-label="Permalink to &quot;堆内存大小&quot;">​</a></h4><p>堆内存在64位系统下最大1.4G，32位系统下最大0.7G，可通过<code>process.memoryUsage()</code>查看内存使用情况</p><p>在node运行时可以通过<code>node --max-old-space-size=xxx test.js</code>或者<code>node --max-new-space-size=xxx test.js</code>（单位为MB）调整内存</p><h4 id="垃圾回收机制" tabindex="-1">垃圾回收机制 <a class="header-anchor" href="#垃圾回收机制" aria-label="Permalink to &quot;垃圾回收机制&quot;">​</a></h4><h5 id="新生代-操作存活的变量" tabindex="-1">新生代：操作存活的变量 <a class="header-anchor" href="#新生代-操作存活的变量" aria-label="Permalink to &quot;新生代：操作存活的变量&quot;">​</a></h5><p>切尼算法</p><p>将内存分为两部分：from和to 内存分配首先使用from 回收过程中将from中<strong>存活的变量</strong>移动到to中，再将from和to交换</p><p>满足两个条件则会转移到老生代:</p><ol><li>已经经历一次垃圾回收还存活</li><li>移动到to前，to中内存超25%</li></ol><h5 id="老生代-操作死亡的变量" tabindex="-1">老生代：操作死亡的变量 <a class="header-anchor" href="#老生代-操作死亡的变量" aria-label="Permalink to &quot;老生代：操作死亡的变量&quot;">​</a></h5><p>mark-sweep：遍历堆中变量，标记存活变量，清除死亡变量</p><p>mark-compact：将内存碎片整合</p><p>优化：增量mark-sweep、增量mark-compact</p><h4 id="堆外内存-buffer-array-不受v8内存限制" tabindex="-1">堆外内存(Buffer Array)：不受v8内存限制 <a class="header-anchor" href="#堆外内存-buffer-array-不受v8内存限制" aria-label="Permalink to &quot;堆外内存(Buffer Array)：不受v8内存限制&quot;">​</a></h4><h4 id="避免内存泄漏" tabindex="-1">避免内存泄漏 <a class="header-anchor" href="#避免内存泄漏" aria-label="Permalink to &quot;避免内存泄漏&quot;">​</a></h4><ol><li>注意全局变量</li><li>注意闭包使用</li><li>及时回收变量内存</li><li>慎用内存缓存</li><li>队列供大于求</li></ol><h4 id="监控定位内存泄漏情况" tabindex="-1">监控定位内存泄漏情况 <a class="header-anchor" href="#监控定位内存泄漏情况" aria-label="Permalink to &quot;监控定位内存泄漏情况&quot;">​</a></h4><p>node-heapdump/node-memwatch的使用</p>',19)])])}const f=e(l,[["render",i]]);export{p as __pageData,f as default};
